/* ==================================================== */
    /* WIDGET: POSTAGEM EM DESTAQUE (CARD PREMIUM MAG TECH) */
    /* ==================================================== */

    /* 1. Título do Widget ("Postagem em Destaque") */
    .FeaturedPost .title {
      font-size: 0.85rem !important;
      text-transform: uppercase;
      letter-spacing: 2px;
      font-weight: 800;
      color: var(--text-main);
      margin-bottom: 20px;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    /* Cria um pequeno LED a piscar ao lado do título para chamar a atenção */
    .FeaturedPost .title::before {
      content: '';
      display: inline-block;
      width: 10px;
      height: 10px;
      background-color: var(--primary);
      border-radius: 50%;
      animation: pulseGlow 2s infinite;
    }

    /* 2. O Cartão Base */
    .FeaturedPost .post-summary {
      display: flex;
      flex-direction: column;
      background-color: var(--surface);
      border: 1px solid var(--border);
      border-radius: 16px;
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    }

    /* Efeito Magnético ao passar o rato no Cartão inteiro */
    .FeaturedPost .post-summary:hover {
      transform: translateY(-6px);
      box-shadow: 0 15px 30px -5px color-mix(in srgb, var(--primary) 15%, transparent);
      border-color: color-mix(in srgb, var(--primary) 40%, transparent);
    }

    /* 3. A Imagem (Agora movida pelo JS, apenas estilizamos) */
    .FeaturedPost .post-summary .image {
      width: 100% !important;
      height: 220px; 
      object-fit: cover; 
      border-bottom: 1px solid var(--border);
      transition: transform 0.6s ease;
      margin-bottom: 0 !important;
    }

    /* Efeito de Zoom Suave na Imagem */
    .FeaturedPost .post-summary:hover .image {
      transform: scale(1.05);
    }

    /* 4. O Título da Notícia */
    .FeaturedPost .post-summary h3 {
      padding: 20px 20px 10px 20px;
      margin: 0;
      font-size: 1.3rem;
      font-weight: 800;
      line-height: 1.3;
      z-index: 2;
      background: var(--surface);
    }

    .FeaturedPost .post-summary h3 a {
      color: var(--text-main);
      text-decoration: none;
      transition: color 0.3s ease;
    }

    .FeaturedPost .post-summary h3 a:hover {
      color: var(--primary);
    }

    /* 5. O Resumo (Snippet) */
    .FeaturedPost .post-summary p {
      padding: 0 20px 15px 20px;
      margin: 0;
      color: var(--text-muted);
      font-size: 0.95rem;
      line-height: 1.6;

      /* Reticências Inteligentes: Corta o texto se passar de 3 linhas */
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;

      z-index: 2;
      background: var(--surface);
    }

    /* 6. Estilo extra para o Botão Injetado pelo JS */
    .FeaturedPost .post-summary .btn {
      transition: all 0.3s ease;
      z-index: 2;
    }
    .FeaturedPost .post-summary .btn:hover {
      background-color: var(--primary-hover);
      transform: translateX(5px); /* Setinha empurra o botão para a direita */
    }

    /* Animação do LED a piscar */
    @keyframes pulseGlow {
      0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--primary) 60%, transparent); }
      70% { box-shadow: 0 0 0 8px transparent; }
      100% { box-shadow: 0 0 0 0 transparent; }
    }

/* ==================================================== */
    /* WIDGET DE IMAGEM PREMIUM (BANNERS E LOGOS)           */
    /* ==================================================== */

    /* 1. A Moldura (O Quadro Exterior) */
    .widget.Image {
      background-color: var(--surface);
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 15px; /* Cria uma margem de respiro em volta da imagem */
      text-align: center;
      box-shadow: var(--shadow-sm);
      transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
      overflow: hidden;
    }

    /* Efeito Magnético ao passar o rato no Widget */
    .widget.Image:hover {
      transform: translateY(-4px);
      box-shadow: 0 10px 25px -5px color-mix(in srgb, var(--primary) 15%, transparent);
      border-color: color-mix(in srgb, var(--primary) 40%, transparent);
    }

    /* 2. A Imagem (Esmaga os tamanhos fixos do Blogger) */
    .widget.Image img {
      width: 100% !important; /* Força a ocupar a largura do quadro */
      max-width: 100% !important;
      height: auto !important; /* Mantém a proporção real da imagem */
      border-radius: 8px; /* Arredonda levemente as pontas da própria imagem */
      transition: transform 0.5s ease;
      display: block;
      margin: 0 auto;
    }

    /* Efeito de "Respiro" (Zoom In suave) na imagem ao passar o rato */
    .widget.Image:hover img {
      transform: scale(1.03);
    }

    /* 3. A Legenda (Caso você decida escrever um texto abaixo da imagem) */
    .widget.Image .caption {
      margin-top: 15px;
      font-size: 0.85rem;
      color: var(--text-muted);
      font-weight: 600;
      letter-spacing: 0.5px;
    }

/* ==================================================== */
    /* WIDGET: MAIS LIDAS (POPULAR POSTS PREMIUM MAG TECH)  */
    /* ==================================================== */

    /* 1. O Título do Widget */
    .PopularPosts h2 {
      font-size: 0.85rem !important;
      text-transform: uppercase;
      letter-spacing: 2px;
      font-weight: 800;
      color: var(--text-main);
      margin-bottom: 20px;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    /* Coloca um ícone de "Fogo" (Trending) antes do título */
    .PopularPosts h2::before {
      content: '\f3fc'; /* Código do ícone Fire do Bootstrap Icons */
      font-family: 'bootstrap-icons';
      color: #ef4444; /* Vermelho chamas/neon */
      font-size: 1.1rem;
    }

    /* 2. O Cartão Base (Fundo do Widget) */
    .PopularPosts .widget-content {
      background-color: var(--surface);
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 20px;
      box-shadow: var(--shadow-sm);
    }

    /* 3. O Motor de Contagem Numérica Automática */
    .PopularPosts ul {
      counter-reset: popular-counter; /* Zera o relógio */
    }

    /* 4. Cada Linha de Notícia */
    .PopularPosts li {
      counter-increment: popular-counter; /* +1 a cada notícia */
      position: relative;
      transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
      border-color: var(--border) !important;
      padding: 12px 0 !important;
    }

    /* Remove a borda do último item para ficar limpo */
    .PopularPosts li:last-child,
    .PopularPosts li.last-no-border {
      border-bottom: none !important;
      padding-bottom: 0 !important;
    }

    /* Efeito Hover: A notícia dá um "passo" para a direita ao passar o rato */
    .PopularPosts li:hover {
      transform: translateX(6px);
    }

    /* 5. A Imagem da Notícia */
    .PopularPosts li img {
      border-radius: 10px !important; /* Um arredondamento mais moderno que os 4px originais */
      box-shadow: 0 4px 10px rgba(0,0,0,0.08);
      transition: transform 0.5s ease;
      z-index: 1;
    }

    /* Efeito de Micro-Zoom e Rotação na Imagem */
    .PopularPosts li:hover img {
      transform: scale(1.1) rotate(3deg);
    }

    /* 6. O Emblema Numérico do Ranking (Surge no Hover!) */
    .PopularPosts li::before {
      content: counter(popular-counter);
      position: absolute;
      top: 8px;
      left: -8px;
      width: 22px;
      height: 22px;
      background-color: var(--primary);
      color: #ffffff;
      font-size: 0.75rem;
      font-weight: 900;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 50%;
      box-shadow: 0 4px 10px color-mix(in srgb, var(--primary) 50%, transparent);
      z-index: 2;
      opacity: 0; /* Começa invisível */
      transform: scale(0.5);
      transition: all 0.3s ease;
    }

    /* Quando passa o rato, o número "salta" na tela */
    .PopularPosts li:hover::before {
      opacity: 1;
      transform: scale(1);
    }

    /* 7. O Título da Notícia */
    .PopularPosts li a {
      color: var(--text-main) !important;
      font-weight: 700 !important;
      line-height: 1.4;
      transition: color 0.3s ease;

      /* Reticências Inteligentes: Corta rigorosamente na 2ª linha para não quebrar a simetria */
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .PopularPosts li:hover a {
      color: var(--primary) !important;
    }


