/* ==================================================== */
/* MOTOR DE MOVIMENTO E REVELAÇÃO (SCROLL REVEAL)      */
/* ==================================================== */

/* Estado inicial: Escondido e um pouco abaixo */
.mag-reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: all 0.8s cubic-bezier(0.25, 1, 0.5, 1);
  will-change: opacity, transform; /* Otimização para placa de vídeo */
}

/* Estado final: Visível e na posição correta */
.mag-reveal.active {
  opacity: 1;
  transform: translateY(0);
}

/* Variação: Surgir da Esquerda */
.reveal-left {
  opacity: 0;
  transform: translateX(-40px);
  transition: all 0.8s ease-out;
}
.reveal-left.active {
  opacity: 1;
  transform: translateX(0);
}

/* Variação: Surgir da Direita */
.reveal-right {
  opacity: 0;
  transform: translateX(40px);
  transition: all 0.8s ease-out;
}
.reveal-right.active {
  opacity: 1;
  transform: translateX(0);
}

/* Delay para itens em lista (para não subirem todos de uma vez) */
.delay-1 { transition-delay: 0.1s; }
.delay-2 { transition-delay: 0.2s; }
.delay-3 { transition-delay: 0.3s; }


